        "child": "main_column"
      },
      {
        "id": "main_column",
        "component": "Column",
        "children": [
          "album_art",
          "song_title",
          "artist_name",
          "progress_slider",
          "controls_row"
        ],
        "align": "stretch"
      },
      {
        "id": "album_art",
        "component": "Image",
