        "variant": "shortText",
        "weight": 1
      },
      {
        "id": "destinationField",
        "component": "TextField",
        "label": "Destination",
        "variant": "shortText",
        "weight": 1
      },
      {
        "id": "dateRow",
        "component": "Row",
        "children": [
