        "label": "Departure Date",
        "value": "",
        "enableDate": true,
        "weight": 1
      },
      {
        "id": "returnField",
        "component": "DateTimeInput",
        "label": "Return Date",
        "value": "",
        "enableDate": true,
        "weight": 1
      },
      {
        "id": "passengerSlider",
        "component": "Slider",
        "label": "Passengers",
        "min": 1,
        "max": 10,
        "value": 1
