      },
      {
        "id": "comment_btn",
        "component": "Button",
        "child": "comment_text",
        "variant": "default",
        "action": {
          "event": {
            "name": "comment"
          }
        }
      },
      {
        "id": "comment_text",
        "component": "Text",
        "text": "💬 Comment",
        "variant": "body"
      },
      {
        "id": "share_btn",
        "component": "Button",
        "child": "share_text",
        "variant": "default",
        "action": {
          "event": {
            "name": "share"
          }
        }
      },
      {
        "id": "share_text",
        "component": "Text",
        "text": "↪️ Share",
        "variant": "body"
      }
    ]
  }
}
