        "description": "Thumbnail View 3",
        "variant": "icon"
      },
      {
        "id": "product_name",
        "component": "Text",
        "text": "Premium Leather Jacket",
        "variant": "h1"
      },
      {
        "id": "product_price",
        "component": "Text",
        "text": "$299.99",
        "variant": "h3"
      },
      {
        "id": "divider_1",
        "component": "Divider",
        "axis": "horizontal"
      },
      {
        "id": "size_picker",
        "component": "ChoicePicker",
        "label": "Select Size",
        "variant": "mutuallyExclusive",
        "options": [
          { "label": "S", "value": "S" },
          { "label": "M", "value": "M" },
          { "label": "L", "value": "L" },
