Here is the interactive chat room interface built with A2UI components, featuring message history cards, a text input field, and a send button.

<a2ui-json>
[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "main",
      "catalogId": "https://a2ui.org/specification/v0_9/catalogs/basic/catalog.json",
      "theme": {
        "primaryColor": "#0078D4",
        "agentDisplayName": "Chat Room"
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "main",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "justify": "spaceBetween",
          "align": "stretch",
          "children": [
            "historyContainer",
            "inputRow"
          ]
        },
        {
          "id": "historyContainer",
          "component": "Column",
          "justify": "start",
          "align": "stretch",
          "children": [
            "msgCard1",
            "msgCard2"
          ]
        },
        {
          "id": "msgCard1",
          "component": "Card",
          "child": "msgContent1"
        },
        {
          "id": "msgContent1",
          "component": "Column",
          "justify": "start",
          "align": "start",
          "children": [
            "msg1Sender",
            "msg1Text"
          ]
        },
        {
          "id": "msg1Sender",
          "component": "Text",
          "text": "**Alice**",
          "variant": "caption"
        },
        {
          "id": "msg1Text",
          "component": "Text",
          "text": "Hi there!",
          "variant": "body"
        },
        {
          "id": "msgCard2",
          "component": "Card",
          "child": "msgContent2"
        },
        {
          "id": "msgContent2",
          "component": "Column",
          "justify": "start",
          "align": "start",
          "children": [
            "msg2Sender",
            "msg2Text"
          ]
        },
        {
          "id": "msg2Sender",
          "component": "Text",
          "text": "**Bob**",
          "variant": "caption"
        },
        {
          "id": "msg2Text",
          "component": "Text",
          "text": "Hello!",
          "variant": "body"
        },
        {
          "id": "inputRow",
          "component": "Row",
          "justify": "spaceBetween",
          "align": "center",
          "children": [
            "messageInput",
            "sendButton"
          ]
        },
        {
          "id": "messageInput",
          "component": "TextField",
          "label": "Type a message...",
          "variant": "shortText",
          "value": {
            "path": "/draftMessage"
          },
          "weight": 1
        },
        {
          "id": "sendButton",
          "component": "Button",
          "variant": "primary",
          "child": "sendButtonText",
          "action": {
            "event": {
              "name": "sendMessage",
              "context": {
                "message": {
                  "path": "/draftMessage"
                }
              }
            }
          }
        },
        {
          "id": "sendButtonText",
          "component": "Text",
          "text": "Send"
        }
      ]
    }
  }
]
</a2ui-json>

