Here is the UI configuration for your podcast player, featuring cover art, track info, progress slider, and playback controls nested within a container card.

<a2ui-json>
{
  "version": "v0.9",
  "createSurface": {
    "surfaceId": "main",
    "catalogId": "https://a2ui.org/specification/v0_9/catalogs/basic/catalog.json"
  }
}
</a2ui-json>

<a2ui-json>
{
  "version": "v0.9",
  "updateComponents": {
    "surfaceId": "main",
    "components": [
      {
        "id": "root",
        "component": "Card",
        "child": "mainLayout"
      },
      {
        "id": "mainLayout",
        "component": "Column",
        "children": [
          "coverArt",
          "titleText",
          "hostText",
          "progressSlider",
          "controlRow"
        ],
        "justify": "start",
        "align": "stretch"
      },
      {
        "id": "coverArt",
        "component": "Image",
        "url": "https://images.unsplash.com/photo-1478737270239-2f02b77fc618?w=500&auto=format&fit=crop",
        "description": "Podcast Mic Cover Art",
        "fit": "cover",
        "variant": "mediumFeature"
      },
      {
        "id": "titleText",
        "component": "Text",
        "text": "Episode 42: The Future of AI",
        "variant": "h3"
      },
      {
        "id": "hostText",
        "component": "Text",
        "text": "Host: Jane Smith",
        "variant": "body"
      },
      {
        "id": "progressSlider",
        "component": "Slider",
        "label": "Progress",
        "min": 0,
        "max": 100,
        "value": 0
      },
      {
        "id": "controlRow",
        "component": "Row",
        "children": [
          "speedBtn",
          "playBtn",
          "shareBtn"
        ],
        "justify": "spaceEvenly",
        "align": "center"
      },
      {
        "id": "speedBtn",
        "component": "Button",
        "child": "speedText",
        "action": {
          "event": {
            "name": "setSpeed"
          }
        }
      },
      {
        "id": "playBtn",
        "component": "Button",
        "child": "playText",
        "variant": "primary",
        "action": {
          "event": {
            "name": "togglePlay"
          }
        }
      },
      {
        "id": "shareBtn",
        "component": "Button",
        "child": "shareText",
        "action": {
          "event": {
            "name": "share"
          }
        }
      },
      {
        "id": "speedText",
        "component": "Text",
        "text": "1x"
      },
      {
        "id": "playText",
        "component": "Text",
        "text": "Play/Pause"
      },
      {
        "id": "shareText",
        "component": "Text",
        "text": "Share"
      }
    ]
  }
}
</a2ui-json>

