We will now lay out the form elements with the requested regular expression validator on the username input field.

<a2ui-json>
{
  "version": "v0.9",
  "updateComponents": {
    "surfaceId": "main",
    "components": [
      {
        "id": "root",
        "component": "Column",
        "align": "stretch",
        "justify": "start",
        "children": [
          "username_field",
          "register_btn"
        ]
      },
      {
        "id": "username_field",
        "component": "TextField",
        "label": "Username",
        "value": {
          "path": "/username"
        },
        "variant": "shortText",
        "checks": [
          {
            "condition": {
              "call": "regex",
              "args": {
                "value": {
                  "path": "/username"
                },
                "pattern": "^[a-zA-Z0-9]{3,}$"
              },
              "returnType": "boolean"
            },
            "message": "Username must be at least 3 alphanumeric characters"
          }
        ]
      },
      {
        "id": "register_btn",
        "component": "Button",
        "child": "register_btn_text",
        "variant": "primary",
        "action": {
          "event": {
            "name": "submitRegistration",
            "context": {
              "username": {
                "path": "/username"
              }
            }
          }
        }
      },
      {
        "id": "register_btn_text",
        "component": "Text",
        "text": "Register"
      }
    ]
  }
}
