content.text:
Here is the sales performance dashboard designed specifically for a Sales Manager tracking the Q2 Report. 

This dashboard provides:
- Quick filters for selecting specific sales regions and timeline ranges.
- Performance insights via highly readable KPI cards.
- Multi-tab support to seamlessly switch between an executive performance summary and detailed sales team leaderboards.
- Actions such as generating and exporting the report.

<a2ui-json>
[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "main",
      "catalogId": "https://a2ui.org/specification/v0_9/catalogs/basic/catalog.json",
      "theme": {
        "primaryColor": "#1E3A8A",
        "agentDisplayName": "Sales Analytics Assistant"
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "main",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "header_row",
            "divider_1",
            "filter_row",
            "divider_2",
            "dashboard_tabs"
          ],
          "align": "stretch"
        },
        {
          "id": "header_row",
          "component": "Row",
          "children": [
            "header_text_col",
            "header_action_btn"
          ],
          "justify": "spaceBetween",
          "align": "center"
        },
        {
          "id": "divider_1",
          "component": "Divider",
          "axis": "horizontal"
        },
        {
          "id": "filter_row",
          "component": "Row",
          "children": [
            "region_picker",
            "date_input"
          ],
          "justify": "start",
          "align": "center"
        },
        {
          "id": "divider_2",
          "component": "Divider",
          "axis": "horizontal"
        },
        {
          "id": "dashboard_tabs",
          "component": "Tabs",
          "tabs": [
            {
              "title": "Overview",
              "child": "tab_overview_card"
            },
            {
              "title": "Team Performance",
              "child": "tab_team_card"
            }
          ]
        },
        {
          "id": "header_text_col",
          "component": "Column",
          "children": [
            "title_text",
            "subtitle_text"
          ]
        },
        {
          "id": "header_action_btn",
          "component": "Button",
          "child": "export_btn_text",
          "variant": "primary",
          "action": {
            "event": {
              "name": "exportReport",
              "context": {
                "format": "PDF",
                "report": "Q2_Sales_Report"
              }
            }
          }
        },
        {
          "id": "region_picker",
          "component": "ChoicePicker",
          "label": "Filter by Region",
          "variant": "mutuallyExclusive",
          "options": [
            {
              "label": "All Regions",
              "value": "all"
            },
            {
              "label": "North America",
              "value": "na"
            },
            {
              "label": "Europe",
              "value": "eu"
            },
            {
              "label": "APAC",
              "value": "apac"
            }
          ],
          "value": [
            "all"
          ]
        },
        {
          "id": "date_input",
          "component": "DateTimeInput",
          "label": "Performance Cutoff Date",
          "value": "2023-06-30",
          "enableDate": true
        },
        {
          "id": "tab_overview_card",
          "component": "Card",
          "child": "overview_layout"
        },
        {
          "id": "tab_team_card",
          "component": "Card",
          "child": "team_layout"
        },
        {
          "id": "title_text",
          "component": "Text",
          "text": "Q2 Sales Report & Performance",
          "variant": "h2"
        },
        {
          "id": "subtitle_text",
          "component": "Text",
          "text": "Manager Portal • Sales Department Active Tracking",
          "variant": "caption"
        },
        {
          "id": "export_btn_text",
          "component": "Text",
          "text": "Export Report PDF"
        },
        {
          "id": "overview_layout",
          "component": "Column",
          "children": [
            "kpi_row",
            "recent_activity_title",
            "activity_list"
          ],
          "align": "stretch"
        },
        {
          "id": "team_layout",
          "component": "Column",
          "children": [
            "team_title",
            "team_list"
          ],
          "align": "stretch"
        },
        {
          "id": "kpi_row",
          "component": "Row",
          "children": [
            "kpi_card_1",
            "kpi_card_2",
            "kpi_card_3"
          ],
          "justify": "spaceBetween"
        },
        {
          "id": "recent_activity_title",
          "component": "Text",
          "text": "Recent Milestone Highlights (Q2)",
          "variant": "h3"
        },
        {
          "id": "activity_list",
          "component": "List",
          "children": [
            "act_1",
            "act_2"
          ],
          "direction": "vertical"
        },
        {
          "id": "team_title",
          "component": "Text",
          "text": "Team Standings (Current Quota Attainment)",
          "variant": "h3"
        },
        {
          "id": "team_list",
          "component": "List",
          "children": [
            "rep_1",
            "rep_2",
            "rep_3"
          ],
          "direction": "vertical"
        },
        {
          "id": "kpi_card_1",
          "component": "Card",
          "child": "kpi_col_1"
        },
        {
          "id": "kpi_card_2",
          "component": "Card",
          "child": "kpi_col_2"
        },
        {
          "id": "kpi_card_3",
          "component": "Card",
          "child": "kpi_col_3"
        },
        {
          "id": "act_1",
          "component": "Text",
          "text": "• **Acme Corp Expansion**: Closed $120,000 Enterprise Suite Upgrade (Assigned to NA Team) on June 14.",
          "variant": "body"
        },
        {
          "id": "act_2",
          "component": "Text",
          "text": "• **Globex ARR Kickoff**: Secured $45,000 annual recurring contract (Assigned to Europe Team) on June 18.",
          "variant": "body"
        },
        {
          "id": "rep_1",
          "component": "Text",
          "text": "🏆 **Sarah Jenkins (North America)**: $480,000 Revenue Generated (110% of Target Quota)",
          "variant": "body"
        },
        {
          "id": "rep_2",
          "component": "Text",
          "text": "🥈 **Miguel Silva (Europe)**: $390,000 Revenue Generated (98% of Target Quota)",
          "variant": "body"
        },
        {
          "id": "rep_3",
          "component": "Text",
          "text": "🥉 **Kenji Takahashi (APAC)**: $310,000 Revenue Generated (92% of Target Quota)",
          "variant": "body"
        },
        {
          "id": "kpi_col_1",
          "component": "Column",
          "children": [
            "kpi_label_1",
            "kpi_value_1"
          ]
        },
        {
          "id": "kpi_col_2",
          "component": "Column",
          "children": [
            "kpi_label_2",
            "kpi_value_2"
          ]
        },
        {
          "id": "kpi_col_3",
          "component": "Column",
          "children": [
            "kpi_label_3",
            "kpi_value_3"
          ]
        },
        {
          "id": "kpi_label_1",
          "component": "Text",
          "text": "Total Booked Revenue",
          "variant": "caption"
        },
        {
          "id": "kpi_value_1",
          "component": "Text",
          "text": "$1,180,000 (+15.4% vs Q1)",
          "variant": "h3"
        },
        {
          "id": "kpi_label_2",
          "component": "Text",
          "text": "Target Pipeline Conversion",
          "variant": "caption"
        },
        {
          "id": "kpi_value_2",
          "component": "Text",
          "text": "82.5% Completed",
          "variant": "h3"
        },
        {
          "id": "kpi_label_3",
          "component": "Text",
          "text": "Average Deal Valuation",
          "variant": "caption"
        },
        {
          "id": "kpi_value_3",
          "component": "Text",
          "text": "$38,400 per contract",
          "variant": "h3"
        }
      ]
    }
  }
]
</a2ui-json>

