content.text:
I've spun up a stunning, cyberpunk-themed Neon Pong game interface for you! 

Grab your virtual paddle and prepare for a high-intensity match against the AI. Moving your mouse over the canvas or using touch swipe controls will slide your paddle up and down. Collisions generate radiant spark particles, and real-time score updates will feed right into the digital scoreboard.

Click **Insert Coin** below to start the game!

<a2ui-json>
{
  "version": "0.9.1",
  "createSurface": {
    "surfaceId": "pong-surface",
    "catalogId": "https://a2ui.org/samples/community/agent/adk/mcp_app_proxy/catalogs/0.9/mcp_app_catalog.json"
  }
}
</a2ui-json>

<a2ui-json>
{
  "version": "0.9.1",
  "updateComponents": {
    "surfaceId": "pong-surface",
    "components": [
      {
        "id": "root",
        "component": "PongLayout",
        "mcpComponent": "pong-game",
        "scoreboardComponent": "pong-scoreboard"
      },
      {
        "id": "pong-scoreboard",
        "component": "PongScoreBoard",
        "playerScore": { "path": "/playerScore" },
        "cpuScore": { "path": "/cpuScore" },
        "commentary": { "path": "/commentary" }
      },
      {
        "id": "pong-game",
        "component": "McpApp",
