            "path": "/commentary"
          }
        },
        {
          "id": "pong-game",
          "component": "McpApp",
          "title": "Neon Pong",
          "htmlContent": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><title>Neon Pong</title><style>body,html{margin:0;padding:0;width:100%;height:100%;overflow:hidden;background-color:#0d0e15;font-family:'Courier New',Courier,monospace;color:#00ffcc;display:flex;flex-direction:column;align-items:center;justify-content:center}#gameContainer{position:relative;width:100%;height:100%;max-width:800px;max-height:500px;box-shadow:0 0 20px #ff007f,0 0 40px #00ffcc;border:3px solid #00ffcc;border-radius:10px}canvas{width:100%;height:100%;display:block;background:radial-gradient(circle,#151821 0%,#0d0e15 100%)}.overlay{position:absolute;top:0;left:0;width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:rgba(13,14,21,0.85);transition:opacity 0.5s ease;z-index:10}.overlay.hidden{opacity:0;pointer-events:none}h1{font-size:3rem;text-transform:uppercase;text-shadow:0 0 10px #ff007f,0 0 20px #ff007f;margin-bottom:20px;color:#ff007f}button{background:transparent;border:2px solid #00ffcc;color:#00ffcc;padding:12px 30px;font-size:1.2rem;font-weight:bold;text-transform:uppercase;cursor:pointer;border-radius:5px;text-shadow:0 0 5px #00ffcc;box-shadow:0 0 10px rgba(0,255,204,0.3);transition:all 0.3s ease}button:hover{background:#00ffcc;color:#0d0e15;box-shadow:0 0 20px #00ffcc}</style></head><body><div id=\"gameContainer\"><div id=\"startOverlay\" class=\"overlay\"><h1>Neon Pong</h1><button id=\"startButton\">Insert Coin</button></div><canvas id=\"gameCanvas\" width=\"800\" height=\"500\"></canvas></div><script>const canvas=document.getElementById('gameCanvas');const ctx=canvas.getContext('2d');const startOverlay=document.getElementById('startOverlay');const startButton=document.getElementById('startButton');let playerScore=0;let cpuScore=0;let gameState='start';const ball={x:canvas.width/2,y:canvas.height/2,radius:8,speed:6,dx:6,dy:4,glowColor:'#ff007f'};const paddleWidth=12;const paddleHeight=80;const player={x:20,y:canvas.height/2-paddleHeight/2,width:paddleWidth,height:paddleHeight,color:'#00ffcc',score:0};const cpu={x:canvas.width-20-paddleWidth,y:canvas.height/2-paddleHeight/2,width:paddleWidth,height:paddleHeight,color:'#00ffcc',score:0,speed:4.5};let particles=[];function createParticles(x,y,color){for(let i=0;i<15;i++){particles.push({x:x,y:y,vx:(Math.random()-0.5)*8,vy:(Math.random()-0.5)*8,radius:Math.random()*3+1,color:color,alpha:1,decay:Math.random()*0.03+0.01})}}function updateParticles(){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx;p.y+=p.vy;p.alpha-=p.decay;if(p.alpha<=0){particles.splice(i,1)}}}function drawParticles(){particles.forEach(p=>{ctx.save();ctx.globalAlpha=p.alpha;ctx.fillStyle=p.color;ctx.shadowBlur=10;ctx.shadowColor=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.radius,0,Math.PI*2);ctx.fill();ctx.restore()})}let mouseY=player.y;canvas.addEventListener('mousemove',(e)=>{const rect=canvas.getBoundingClientRect();mouseY=(e.clientY-rect.top)*(canvas.height/rect.height)-player.height/2});canvas.addEventListener('touchmove',(e)=>{const rect=canvas.getBoundingClientRect();const touch=e.touches[0];mouseY=(touch.clientY-rect.top)*(canvas.height/rect.height)-player.height/2;e.preventDefault()},{passive:false});function update(){if(gameState!=='playing')return;player.y+=(mouseY-player.y)*0.2;if(player.y<5)player.y=5;if(player.y>canvas.height-player.height-5)player.y=canvas.height-player.height-5;const targetY=ball.y-cpu.height/2;cpu.y+=(targetY-cpu.y)*0.08;if(cpu.y<5)cpu.y=5;if(cpu.y>canvas.height-cpu.height-5)cpu.y=canvas.height-cpu.height-5;ball.x+=ball.dx;ball.y+=ball.dy;if(ball.y-ball.radius<0){ball.y=ball.radius;ball.dy=-ball.dy;createParticles(ball.x,ball.y,'#ff007f')}else if(ball.y+ball.radius>canvas.height){ball.y=canvas.height-ball.radius;ball.dy=-ball.dy;createParticles(ball.x,ball.y,'#ff007f')}if(ball.dx<0){if(ball.x-ball.radius<player.x+player.width&&ball.y>player.y&&ball.y<player.y+player.height){ball.dx=-ball.dx;const relativeY=(ball.y-(player.y+player.height/2))/(player.height/2);ball.dy=relativeY*5;ball.speed+=0.2;ball.dx=Math.sign(ball.dx)*ball.speed;createParticles(ball.x,ball.y,player.color)}}else{if(ball.x+ball.radius>cpu.x&&ball.y>cpu.y&&ball.y<cpu.y+cpu.height){ball.dx=-ball.dx;const relativeY=(ball.y-(cpu.y+cpu.height/2))/(cpu.height/2);ball.dy=relativeY*5;ball.speed+=0.2;ball.dx=Math.sign(ball.dx)*ball.speed;createParticles(ball.x,ball.y,cpu.color)}}if(ball.x<0){cpuScore++;notifyScore();resetBall()}else if(ball.x>canvas.width){playerScore++;notifyScore();resetBall()}updateParticles()}function resetBall(){ball.x=canvas.width/2;ball.y=canvas.height/2;ball.speed=6;ball.dx=-ball.dx;ball.dy=(Math.random()-0.5)*6}function notifyScore(){const commentaries=[\"Unbelievable shot!\",\"What a recovery!\",\"The crowd is going wild!\",\"Precision power!\",\"Total control!\"];const comm=commentaries[Math.floor(Math.random()*commentaries.length)];window.parent.postMessage({type:'a2ui:updateDataModel',surfaceId:'pong-surface',path:'/',value:{playerScore:playerScore,cpuScore:cpuScore,commentary:comm}},'*')}function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='rgba(0, 255, 204, 0.1)';ctx.lineWidth=4;ctx.setLineDash([10,10]);ctx.beginPath();ctx.moveTo(canvas.width/2,0);ctx.lineTo(canvas.width/2,canvas.height);ctx.stroke();ctx.setLineDash([]);drawPaddle(player.x,player.y,player.width,player.height,player.color);drawPaddle(cpu.x,cpu.y,cpu.width,cpu.height,cpu.color);ctx.save();ctx.fillStyle=ball.glowColor;ctx.shadowBlur=15;ctx.shadowColor=ball.glowColor;ctx.beginPath();ctx.arc(ball.x,ball.y,ball.radius,0,Math.PI*2);ctx.fill();ctx.restore();drawParticles()}function drawPaddle(x,y,w,h,color){ctx.save();ctx.fillStyle=color;ctx.shadowBlur=15;ctx.shadowColor=color;ctx.fillRect(x,y,w,h);ctx.restore()}function loop(){update();draw();requestAnimationFrame(loop)}startButton.addEventListener('click',()=>{startOverlay.classList.add('hidden');gameState='playing';playerScore=0;cpuScore=0;notifyScore()});loop();</script></body></html>"
        }
