          "label": "Email",
          "value": {
            "path": "/email"
          },
          "variant": "shortText"
        },
        {
          "id": "input_phone",
          "component": "TextField",
          "label": "Phone",
          "value": {
            "path": "/phone"
          },
          "variant": "shortText"
        },
        {
          "id": "input_resume",
          "component": "TextField",
          "label": "Resume URL",
          "value": {
            "path": "/resumeUrl"
          },
          "variant": "shortText"
