            {
              "label": "2-5",
              "value": "2-5"
            },
            {
              "label": "5+",
              "value": "5+"
            }
          ],
          "value": {
            "path": "/experience"
          },
          "displayStyle": "chips"
        },
        {
          "id": "divider1",
          "component": "Divider",
          "axis": "horizontal"
        },
        {
          "id": "submit_btn",
          "component": "Button",
          "child": "submit_btn_text",
          "variant": "primary",
          "action": {
            "event": {
              "name": "submit_application",
              "context": {
                "name": {
                  "path": "/name"
                },
                "email": {
                  "path": "/email"
                },
                "phone": {
                  "path": "/phone"
                },
                "resume": {
                  "path": "/resumeUrl"
                },
                "experience": {
                  "path": "/experience"
                }
              }
            }
          }
        },
        {
          "id": "submit_btn_text",
          "component": "Text",
          "text": "Submit Application",
          "variant": "body"
        }
      ]
    }
  }
]
