Here is the project management dashboard UI stream, split into three sequential JSON messages.

### 1. Create Surface Message
This initializes the surface where the project dashboard will be rendered.

<a2ui-json>
{
  "version": "v0.9",
  "createSurface": {
    "surfaceId": "main",
    "catalogId": "https://a2ui.org/specification/v0_9/catalogs/basic/catalog.json"
  }
}
</a2ui-json>

### 2. Update Components Message
This constructs the dashboard's layout using top-down hierarchical ordering.

<a2ui-json>
{
  "version": "v0.9",
  "updateComponents": {
    "surfaceId": "main",
    "components": [
      {
        "id": "root",
        "component": "Column",
        "children": [
          "headerText",
          "projectList"
        ]
      },
      {
        "id": "headerText",
        "component": "Text",
        "text": "# Project Dashboard",
        "variant": "h1"
      },
      {
        "id": "projectList",
        "component": "List",
        "children": {
          "componentId": "projectCard",
          "path": "/projects"
        }
      },
      {
        "id": "projectCard",
        "component": "Card",
        "child": "projectCardContent"
      },
      {
        "id": "projectCardContent",
        "component": "Column",
        "children": [
          "projectTitle",
          "taskList"
        ]
      },
      {
        "id": "projectTitle",
        "component": "Text",
        "text": {
          "path": "title"
        },
        "variant": "h2"
      },
      {
        "id": "taskList",
        "component": "List",
        "children": {
          "componentId": "taskColumn",
          "path": "tasks"
        }
      },
      {
        "id": "taskColumn",
        "component": "Column",
        "children": [
          "taskDesc",
          "assigneeRow",
          "subtaskList"
        ]
      },
      {
        "id": "taskDesc",
        "component": "Text",
        "text": {
          "path": "description"
        },
        "variant": "body"
      },
      {
        "id": "assigneeRow",
        "component": "Row",
        "children": [
          "assigneeName",
          "assigneeRole"
        ],
        "justify": "start",
        "align": "center"
      },
      {
        "id": "assigneeName",
        "component": "Text",
        "text": {
          "path": "assignee/name"
        },
        "variant": "caption"
      },
      {
        "id": "assigneeRole",
        "component": "Text",
        "text": {
          "path": "assignee/role"
        },
        "variant": "caption"
      },
      {
        "id": "subtaskList",
        "component": "List",
        "children": {
          "componentId": "subtaskText",
          "path": "subtasks"
        }
      },
      {
        "id": "subtaskText",
        "component": "Text",
        "text": {
          "path": "title"
        },
        "variant": "body"
      }
    ]
  }
}
</a2ui-json>

### 3. Update Data Model Message
This populates the project management dashboard with sample mock data.

<a2ui-json>
{
  "version": "v0.9",
  "updateDataModel": {
    "surfaceId": "main",
    "path": "/",
    "value": {
      "projects": [
        {
          "title": "Quantum Leap Project",
          "tasks": [
            {
              "description": "Establish core temporal stabilization field",
              "assignee": {
                "name": "Dr. Sam Beckett",
                "role": "Lead Physicist"
              },
              "subtasks": [
                {
                  "title": "Calibrate handlink sync ratios"
                },
                {
                  "title": "Verify micro-fusion power cells"
                }
              ]
            },
            {
              "description": "Coordinate localized holographic projection",
              "assignee": {
                "name": "Rear Admiral Al Calavicci",
                "role": "Project Observer"
              },
              "subtasks": [
                {
                  "title": "Adjust imaging matrix resolution"
                }
              ]
            }
          ]
        }
      ]
    }
  }
}
</a2ui-json>

